#include <iostream>
#include <string>
#include <utility>
using namespace std;

int main() {
    string src = "Hello, World!";
    cout << "before: " << src << endl;

    string dst = std::move(src);
    cout << "dst: " << dst << endl;
    cout << "src: [" << src << "]" << endl;
    return 0;
}
